    internal static int AfSource(emon.Port.Cells res, int which) {
        // One figure that is the candidate `which` names, no answers; the number of requests it makes and its reason (or -1):
        // 0 a whole image (status 0, no flags): its own, no request; 1 the same with `overlaid`; 2 `colorspace`; 3 `codec`; 4 `part` (page-sized);
        // 5 `too-large`; 6 `budget`; 7 a region candidate; 8 a whole image that is `clip-bbox`; 9 `transformed`.
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells assets = emon.Port.NewCells();
        emon.Port.Cells uses = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells ans = emon.Port.NewCells();
        emon.Port.Cells rq = emon.Port.NewCells();
        emon.Port.Cells box = emon.Port.NewCells();
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Cells rows = emon.Port.NewCells();
        emon.Port.Cells tmp = emon.Port.NewCells();
        emon.Port.Cells rec = emon.Port.NewCells();
        emon.Port.Buf cbytes = emon.Port.NewBuf();
        emon.Port.Buf abytes = emon.Port.NewBuf();
        emon.Port.Buf z = emon.Port.NewBuf();
        emon.Port.BitmapSet bms = emon.Port.NewBitmapSet();
        int status = 0;
        int flags = 0;
        int kori = -1;
        int n = 0;
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Model.PageNew(pages, 1, 61200, 79200, 0, Model.PkVector());
        emon.Port.BufPush(cbytes, 97);
        emon.Port.BufPush(cbytes, 97);
        emon.Port.BufPush(cbytes, 97);
        emon.Port.BufPush(cbytes, 97);
        if (which == 1) {
            flags = Model.AfgOverlaid();
        }
        if (which == 2) {
            status = Model.NzColorspace();
        }
        if (which == 3) {
            status = Model.NzCodec();
        }
        if (which == 4) {
            status = Model.NzPart();
        }
        if (which == 5) {
            status = Model.NzTooLarge();
        }
        if (which == 6) {
            status = Model.NzBudget();
        }
        if (which == 7) {
            status = Model.NzVector();
            kori = -2;
        }
        if (which == 8) {
            flags = 2;
        }
        if (which == 9) {
            flags = 4;
        }
        if (which == 4) {
            AfCand(cand, 1, 0, 0, 61200, 79200, status, flags, kori, 5, 0, 4);
        } else {
            AfCand(cand, 1, 10000, 10000, 30000, 30000, status, flags, kori, 5, 0, 4);
        }
        if (which == 4) {
            n = AfNode(nodes, regions, 0, Model.NkFigure(), Model.FgUnknown(), 1, 0, 0, 61200, 79200);
        } else {
            n = AfNode(nodes, regions, 0, Model.NkFigure(), Model.FgUnknown(), 1, 10000, 10000, 30000, 30000);
        }
        Model.NodeSetAttrInt(nodes, attrs, n, Model.FkImage(), 0);
        AfBoxcells(box);
        Asset.AsRunFigures(nodes, attrs, regions, pages, cand, cbytes, assets, uses, abytes, 4194304, 33554432, 0, 150, 4194304, 3, 1234, 0, ans, rq, bms, ws, z, rows, tmp, rec, box);
        emon.Port.CellsDrop(res, 0);
        emon.Port.CellsPush(res, Plan.RecCount(rq));
        emon.Port.CellsPush(res, Model.NodeAttrIntOr(nodes, attrs, n, Model.FkNoasset(), -1));
        emon.Port.CellsPush(res, Model.NodeAttrIntOr(nodes, attrs, n, Model.FkAsset(), -1));
        return 0;
    }
    [Xunit.Fact]
    public static void TestWhichFiguresAreTheImageAndWhichAreRendered() {
        emon.Port.Cells res = emon.Port.NewCells();
        AfSource(res, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 0, "a whole clean image is its own: no request");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 2), 0, "it is asset 0");
        AfSource(res, 1);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "paint over it (overlaid): rendered, a crop is asked");
        AfSource(res, 8);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "a clip that is not a rectangle (clip-bbox): rendered");
        AfSource(res, 9);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "a placement that is not rectilinear (transformed): rendered");
        AfSource(res, 2);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "colorspace at images is rendered at figures");
        AfSource(res, 3);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "so is codec");
        AfSource(res, 4);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "a page-sized image in a PDF is rendered (its pixels need the host's decode-img, D563)");
        AfSource(res, 7);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 1, "a region candidate is rendered");
        AfSource(res, 5);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 0, "an image too large is not rendered");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 1), Model.NzTooLarge(), "it says so");
        AfSource(res, 6);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 0, "a budget reason is the candidate's own");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 1), Model.NzBudget(), "it says so");
    }
