    internal static int AfPath(emon.Port.Cells pa, int page, int x0, int y0, int x1, int y1, int flags, int vis) {
        // A path row (stride 24) with a page, a box, flags (`pg`: clip 4) and a verdict (`vis`, cell 19).
        int r = emon.Port.CellsLen(pa) / 24;
        int f = 0;
        while (f < 24) {
            emon.Port.CellsPush(pa, 0);
            f += 1;
        }
        emon.Port.CellsSet(pa, (r * 24) + 0, page);
        emon.Port.CellsSet(pa, (r * 24) + 2, x0);
        emon.Port.CellsSet(pa, (r * 24) + 3, y0);
        emon.Port.CellsSet(pa, (r * 24) + 4, x1);
        emon.Port.CellsSet(pa, (r * 24) + 5, y1);
        emon.Port.CellsSet(pa, (r * 24) + 11, flags);
        emon.Port.CellsSet(pa, (r * 24) + 19, vis);
        return r;
    }
    internal static int AfPages(emon.Port.Cells pg, int n) {
        // n page records (16 cells) of 612 x 792 pt: media and crop box, no rotation.
        int i = 0;
        while (i < n) {
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 61200);
            emon.Port.CellsPush(pg, 79200);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 61200);
            emon.Port.CellsPush(pg, 79200);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            emon.Port.CellsPush(pg, 0);
            i += 1;
        }
        return 0;
    }
    [Xunit.Fact]
    public static void TestVectorArtIsAClusterOfPaths() {
        // page 1: four paths 1 pt apart (a chart's axes and bars) form one region; two far-off paths are no figure (a lone path is a rule); a clip
        // and a hidden path join nothing; a page-sized path (a background) is not part of one. Page 2: three paths that sit
        // under an image's visible box are the image's, not a region. Page 3: a cluster narrower than 18 pt is no figure.
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells cl = emon.Port.NewCells();
        AfPages(pg, 3);
        AfPath(pa, 1, 10000, 10000, 30000, 10100, 0, 0);
        AfPath(pa, 1, 10000, 10000, 10100, 30000, 0, 0);
        AfPath(pa, 1, 10200, 20000, 15000, 29900, 0, 0);
        AfPath(pa, 1, 15100, 18000, 18000, 29900, 0, 0);
        AfPath(pa, 1, 40000, 60000, 50000, 60100, 0, 0);
        AfPath(pa, 1, 45000, 70000, 50000, 70100, 0, 0);
        AfPath(pa, 1, 20000, 12000, 30000, 25000, 4, 0);
        AfPath(pa, 1, 20000, 40000, 30000, 45000, 0, 3);
        AfPath(pa, 1, 0, 0, 61200, 79200, 0, 0);
        AfPath(pa, 2, 10000, 10000, 30000, 10100, 0, 0);
        AfPath(pa, 2, 10000, 10000, 10100, 30000, 0, 0);
        AfPath(pa, 2, 10200, 20000, 15000, 29900, 0, 0);
        AfPath(pa, 3, 10000, 10000, 11500, 10100, 0, 0);
        AfPath(pa, 3, 10000, 10000, 10100, 11500, 0, 0);
        AfPath(pa, 3, 10800, 10800, 11500, 10900, 0, 0);
        // the image on page 2: a candidate row of kind -1 over the whole cluster
        AfCand(cand, 2, 5000, 5000, 35000, 35000, 0, 0, -1, 1, 0, 0);
        Asset.AsVectorRegions(pa, pg, cand, cl);
        emon.Testport.AssertEq(Asset.AsCount(cand), 2, "the image's row and one region");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 0), 1, "on page 1");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 5), 10000, "the cluster's left");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 6), 10000, "its top");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 7), 30000, "its right");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 8), 30000, "its bottom");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 27), -2, "a region candidate");
        emon.Testport.AssertEq(Asset.AsGet(cand, 1, 9), Model.NzVector(), "whose status is vector");
    }
